<script setup lang="ts">
import {ref,reactive,onMounted,computed} from 'vue';import {useRoute,useRouter} from 'vue-router';import {admin,upload} from '../../../shared/api';import type {ProductWrite,AdminPet,Asset} from '../../../shared/adminTypes';import {useLoad} from '../../../shared/useLoad';import {ElMessage} from 'element-plus'
const route=useRoute(),router=useRouter(),pet=ref<AdminPet>(),assets=ref<Asset[]>([]),price=ref(0),tags=ref(''),publishOpen=ref(false),review=reactive({healthy:false,quarantine:false,note:''}),{loading,error,run}=useLoad()
const form=reactive<ProductWrite>({name:'',category:'dog',breed:'',priceAmount:0,gender:'male',ageMonths:3,birthDate:null,weightKg:1,color:'',personalityTags:[],vaccineStatus:'待核实',dewormStatus:'待核实',description:'',feedingNotes:'',healthDescription:'',imageFileIds:[],videoFileId:null,quarantine:null,isRecommended:false,recommendationOrder:0});const certificate=reactive({certificateNo:'',publicImageFileIds:[] as string[],originalFileIds:[] as string[],validUntil:null as string|null})
const locked=computed(()=>pet.value&&['reserved','sold'].includes(pet.value.status))
onMounted(()=>{if(route.params.id!=='new')void run(async()=>{pet.value=await admin('GET',`/admin/pets/${route.params.id}`);for(const key of Object.keys(form) as (keyof ProductWrite)[])if(key in pet.value!)Object.assign(form,{[key]:pet.value![key]});assets.value=pet.value!.assets;price.value=form.priceAmount/100;tags.value=form.personalityTags.join('、');if(form.quarantine)Object.assign(certificate,form.quarantine)})})
async function attach(event:Event,purpose:string){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;await run(async()=>{const asset=await upload('admin',file,purpose) as {id:string;publicUrl?:string};assets.value.push({id:asset.id,originalName:file.name,publicUrl:asset.publicUrl||null,purpose});if(purpose==='pet_image')form.imageFileIds.push(asset.id);else if(purpose==='pet_video')form.videoFileId=asset.id;else certificate.publicImageFileIds.push(asset.id)})}
async function save(){await run(async()=>{if(!form.name.trim()||!form.breed.trim()||!form.description.trim()||price.value<=0)throw new Error('请填写宠物名称、品种、介绍和有效价格');if(!form.imageFileIds.length)throw new Error('请至少上传一张宠物照片');const body:ProductWrite={...form,priceAmount:Math.round(price.value*100),personalityTags:tags.value.split(/[、,，]/).map(s=>s.trim()).filter(Boolean),quarantine:certificate.certificateNo?{...certificate}:null};const result=await admin<AdminPet>(pet.value?'PUT':'POST',pet.value?`/admin/pets/${pet.value.id}`:'/admin/pets',pet.value?{...body,version:pet.value.version}:body);ElMessage.success('档案已保存');await router.replace(`/pets/${result.id}`);pet.value=result})}
async function publish(){await run(async()=>{await admin('POST',`/admin/pets/${pet.value!.id}/publish`,{version:pet.value!.version,healthyForSale:review.healthy,quarantineVerified:review.quarantine,reviewNote:review.note});ElMessage.success('核验完成，宠物已上架');publishOpen.value=false;await router.push('/pets')})}
</script>
<template><div><div class="editor-layout"><section class="panel"><p class="eyebrow">INDIVIDUAL PROFILE</p><h2>{{pet?.name||'新伙伴'}} · 个体档案</h2><el-alert v-if="locked" title="此个体已关联交易，只读展示原始档案。" type="info" :closable="false"/><el-form label-position="top" :disabled="Boolean(locked)"><div class="form-grid"><el-form-item label="宠物名称"><el-input v-model="form.name" required maxlength="80"/></el-form-item><el-form-item label="类型"><el-select v-model="form.category"><el-option label="狗狗" value="dog"/><el-option label="猫咪" value="cat"/></el-select></el-form-item><el-form-item label="品种"><el-input v-model="form.breed" required maxlength="50"/></el-form-item><el-form-item label="售价（元）"><el-input-number v-model="price" :min="0.01" :precision="2" :max="1000000"/></el-form-item><el-form-item label="性别"><el-select v-model="form.gender"><el-option label="弟弟" value="male"/><el-option label="妹妹" value="female"/></el-select></el-form-item><el-form-item label="月龄"><el-input-number v-model="form.ageMonths" :min="0" :max="360"/></el-form-item><el-form-item label="体重（kg）"><el-input-number v-model="form.weightKg" :min="0.01" :max="200" :precision="2"/></el-form-item><el-form-item label="毛色"><el-input v-model="form.color" required maxlength="30"/></el-form-item></div><el-form-item label="性格标签（用顿号分隔）"><el-input v-model="tags"/></el-form-item><el-form-item label="疫苗记录"><el-input v-model="form.vaccineStatus" required type="textarea" maxlength="500"/></el-form-item><el-form-item label="驱虫记录"><el-input v-model="form.dewormStatus" required type="textarea" maxlength="500"/></el-form-item><el-form-item label="个体介绍"><el-input v-model="form.description" required type="textarea" :rows="3"/></el-form-item><el-form-item label="饲养要点"><el-input v-model="form.feedingNotes" required type="textarea" :rows="3"/></el-form-item><el-form-item label="健康说明"><el-input v-model="form.healthDescription" required type="textarea" :rows="3"/></el-form-item><el-form-item label="检疫证明编号"><el-input v-model="certificate.certificateNo" maxlength="100"/></el-form-item><el-form-item label="证明有效期（有据可填）"><el-date-picker v-model="certificate.validUntil" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="宠物视频（选填，MP4）"><input type="file" accept="video/mp4" :disabled="Boolean(locked)||loading" @change="attach($event,'pet_video')"><small>已关联：{{form.videoFileId||'暂无视频'}}</small><el-button v-if="form.videoFileId" link @click="form.videoFileId=null">移除视频</el-button></el-form-item><el-form-item label="公开证明图片"><input class="native-upload" type="file" accept=".jpg,.jpeg,.png" :disabled="Boolean(locked)||loading" @change="attach($event,'quarantine_public')"><small>已关联 {{certificate.publicImageFileIds.length}} 份证明图片。请上传此个体的有效材料。</small></el-form-item></el-form></section><aside><img v-if="assets.find(a=>a.purpose==='pet_image')?.publicUrl" class="editor-photo" :src="assets.find(a=>a.purpose==='pet_image')!.publicUrl!" alt="宠物主图"><div class="asset-grid"><img v-for="asset in assets.filter(a=>a.purpose==='pet_image').slice(1)" :key="asset.id" :src="asset.publicUrl!" :alt="asset.originalName"></div><label class="small muted">添加宠物照片<input class="native-upload" type="file" accept=".jpg,.jpeg,.png,.webp" :disabled="Boolean(locked)||loading||form.imageFileIds.length>=9" @change="attach($event,'pet_image')"></label><div class="panel stack" style="margin-top:20px"><el-checkbox v-model="form.isRecommended" :disabled="Boolean(locked)">首页推荐</el-checkbox><el-button v-if="!locked" type="primary" @click="save" :loading="loading">保存档案</el-button><el-button v-if="pet?.status==='off'" @click="publishOpen=true">提交上架核验</el-button><el-button @click="$router.push('/pets')">返回列表</el-button><p class="small">新建个体先保存为未上架，补齐有效证明后由店主人工核验。</p><el-alert v-if="error" :title="error" type="error" :closable="false"/></div></aside></div></div><el-dialog v-model="publishOpen" title="确认个体健康与证明" width="480px"><div class="stack"><el-checkbox v-model="review.healthy">已现场确认个体健康且适合出售</el-checkbox><el-checkbox v-model="review.quarantine">已核验此个体检疫证明真实有效</el-checkbox><el-input v-model="review.note" type="textarea" placeholder="请填写实际核验记录" :rows="4"/></div><template #footer><el-button @click="publishOpen=false">取消</el-button><el-button type="primary" :disabled="!review.healthy||!review.quarantine||!review.note.trim()" :loading="loading" @click="publish">确认核验并上架</el-button></template></el-dialog></template>
